import time
from cryptography.hazmat.primitives.asymmetric import dh
import secrets

P, Q, G = None, None, None
def generate_global_parameters(generate_new=False, use_library=False, generator=2, key_size=2048):
    global P, Q, G
    print(f"Generating global parameters with {("library" if use_library else "custom")} for: {generator}, {key_size}")
    start_time = time.time_ns()
    if not generate_new:
        # public parameters for Schnorr protocol, using a 2048-bit safe prime for P, which means Q = (P-1)//2 is also prime, and G is a generator of the subgroup of order Q.
        P = 11731722534755988379582498904317031585514431212880510373180315650809605302410493595610739947214327053090791642864835392206070266585210162380812213540641579
        Q = (P - 1) // 2
        # generator of subgroup order Q (quadratic residue)
        G = 4
    else:
        if use_library:
            parameters = dh.generate_parameters(generator=generator, key_size=key_size)
            P = parameters.parameter_numbers().p
            G = parameters.parameter_numbers().g
            Q = (P - 1) // 2
        else:
            parameters = dh.generate_parameters(generator=generator, key_size=key_size)
            P = parameters.parameter_numbers().p
            Q = (P - 1) // 2
            temp_h = secrets.randbelow(P-3) + 2 # more secure random, uses CSPRNG (Cryptographically Secure Pseudo-Random Number Generator), can be slow
            # g = h^2 mod p
            G = pow(temp_h, 2, P)
            # Verificam ca: g != 1 si g^q mod p == 1
            while G == 1 or pow(G, Q, P) != 1:
                temp_h = secrets.randbelow(P-3) + 2
                G = pow(temp_h, 2, P)
                print("Trying h:", temp_h, "g:", G)
    #measure time in ms 
    end_time = time.time_ns()

    print(f"Global parameters generated in {(end_time - start_time) / 1000000:.6f} ms")
    print(f"P = {P}")
    print(f"G = {G}")
    print(f"Q = {Q}")
    print(f"P este prim sigur (p = 2q + 1)? -> {P == 2 * Q + 1}")

 
